// Novidades 08-09/10: documentos com vencimento (sem número), encomendas rastreadas e orçamento do mês.
const TZ = 'America/Sao_Paulo';
const out = $input.first().json;
const r = out && out.resposta;
if (!r || !r.ok) return [{ json: out }];
const d = $('Decidir').first().json;
const linhas = (n) => { try { return $(n).all().map((i) => i.json).filter((x) => x && x.id !== undefined && x.id !== null); } catch (e) { return []; } };
const num = (v) => Number(v) || 0;
const semAc = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const ehTotal = (c) => /^(total|geral|mes|mensal|todos)$/.test(semAc(c));
const hoje0 = DateTime.now().setZone(TZ).startOf('day');
const ROT = { cnh: 'CNH', rg: 'RG', passaporte: 'Passaporte', visto: 'Visto', seguro: 'Seguro', contrato: 'Contrato', garantia: 'Garantia', certificado: 'Certificado', outro: 'Documento' };
r.documentos = linhas('Dados: documentos').filter((x) => x.autor === d.autor && String(x.status || 'ativo') === 'ativo' && x.vencimento).map((x) => {
  const v = DateTime.fromISO(String(x.vencimento).slice(0, 10), { zone: TZ });
  return { tipo: ROT[String(x.documento || 'outro')] || 'Documento', descricao: String(x.descricao || '').replace(/[0-9][0-9.\-\/ ]{4,}[0-9]/g, '•••').slice(0, 80), vencimento: String(x.vencimento).slice(0, 10), dias: v.isValid ? Math.round(v.diff(hoje0, 'days').days) : null };
}).sort((a, b) => a.vencimento.localeCompare(b.vencimento)).slice(0, 30);
const EST = { NotFound: 'Aguardando a primeira atualização', InfoReceived: 'Postagem registrada', InTransit: 'Em trânsito', Expired: 'Sem atualização há muito tempo', AvailableForPickup: 'Disponível para retirada', OutForDelivery: 'Saiu para entrega', DeliveryFailure: 'Tentativa de entrega sem sucesso', Delivered: 'Entregue', Exception: 'Problema na entrega' };
r.encomendas = linhas('Dados: rastreios').filter((x) => String(x.cliente || x.telefone || '') === String(d.telefone)).map((x) => ({
  codigo: String(x.codigo || '').slice(0, 40), apelido: String(x.apelido || '').slice(0, 60),
  status: x.entregue_em ? 'Entregue' : (EST[String(x.status_17 || '')] || 'Acompanhando'), entregue: !!x.entregue_em,
  ultimo: String(x.ultimo_evento || '').slice(0, 160), local: String(x.ultimo_local || '').slice(0, 80), quando: String(x.ultimo_evento_em || x.atualizado_em || x.criado_em || '')
})).sort((a, b) => (a.entregue - b.entregue) || b.quando.localeCompare(a.quando)).slice(0, 30);
const tot = linhas('Dados: orçamentos').find((o) => o.pessoa === d.autor && o.ativo !== false && num(o.limite) > 0 && ehTotal(o.categoria));
const usado = num(r.resumo && r.resumo.gastos);
r.orcamento_mes = tot ? { limite: Math.round(num(tot.limite) * 100) / 100, usado, pct: Math.round(usado / num(tot.limite) * 100) } : null;
// o orçamento geral não é uma categoria: tira a barra "Total" vazia que o limite criaria
if (Array.isArray(r.categorias)) r.categorias = r.categorias.filter((c) => !(ehTotal(c.nome) && !num(c.valor)));
if (r.vazio && (r.documentos.length || r.encomendas.length)) r.vazio = false;
return [{ json: out }];
